const formatBRL = v => v == null ? 'Não disponível' : v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const formatNumber = (v, compact = true) => { if (v == null) return 'Não disponível'; if (!compact) return v.toLocaleString('pt-BR'); if (v >= 1000000) return (v/1000000).toFixed(1).replace('.',',')+' mi'; if (v >= 1000) return (v/1000).toFixed(v >= 10000 ? 0 : 1).replace('.',',')+' mil'; return v.toLocaleString('pt-BR'); };
const pct = v => `${String(v).replace('.',',')}%`;
const escapeHTML = str => String(str).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const savedKey = 'central-tiktok-saved';
