function persist() { localStorage.setItem(savedKey, JSON.stringify(saved)); localStorage.setItem(listsKey, JSON.stringify(lists)); localStorage.setItem(settingsKey, JSON.stringify(settings)); }
function toast(message) { const el = document.getElementById('toast'); el.textContent = message; el.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => el.classList.remove('show'), 2600); }
function isSaved(id) { return saved.includes(id); }
function getProduct(id) { return products.find(p => p.id === id); }
function tagClass(tag) { return /Estoque|Caindo|Saturado/.test(tag) ? 'red' : /Novo|Pouca/.test(tag) ? 'blue' : /comissão|Crescendo|Alta/.test(tag) ? 'green' : 'amber'; }
function header(title, subtitle, action='') { return `<div class="page-heading"><div><div class="eyebrow">Central TikTok / ${escapeHTML(title)}</div><h1>${escapeHTML(title)}</h1><p class="page-subtitle">${subtitle}</p></div>${action ? `<div class="page-actions">${action}</div>` : ''}</div>`; }
function metric(label, value, foot, icon) { return `<div class="metric-card"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`; }
function svgChart(kind='area') { const path = kind === 'area' ? 'M0,132 C40,126 54,112 88,119 S150,91 187,101 S243,68 274,81 S328,50 365,61 S427,23 474,43 S527,16 566,31 S625,18 680,23 V160 H0 Z' : 'M0,127 C65,112 77,119 126,88 S197,101 239,75 S302,92 345,55 S428,74 475,42 S548,55 600,26 S647,41 680,15'; return `<div class="chart-placeholder"><svg viewBox="0 0 680 180" preserveAspectRatio="none"><defs><linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1479F5" stop-opacity=".18"/><stop offset="1" stop-color="#1479F5" stop-opacity="0"/></linearGradient></defs><line class="chart-grid-line" x1="0" y1="35" x2="680" y2="35"/><line class="chart-grid-line" x1="0" y1="78" x2="680" y2="78"/><line class="chart-grid-line" x1="0" y1="121" x2="680" y2="121"/>${kind === 'area' ? `<path class="chart-area" d="${path}"/>` : ''}<path class="chart-line" d="${path.replace(' V160 H0 Z','')}"/>${[0,1,2,3,4,5].map((_,i)=>`<circle class="chart-dot" cx="${60+i*122}" cy="${[127,119,101,81,61,23][i]}" r="3"/>`).join('')}</svg></div>`; }

